'use strict';
let csrf = '';
async function api(path, data) {
  const response = await fetch(path, {method:data === undefined ? 'GET':'POST', credentials:'same-origin',headers:data === undefined ? {}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data === undefined ? undefined:JSON.stringify(data)});
  let result;try{result=await response.json();}catch{throw new Error("El servidor devolvió una respuesta no válida (HTTP "+response.status+").");}
  if (!response.ok) {if(response.status === 401 && document.body.dataset.page === 'dashboard') location.replace('/'); const error=new Error(result.error || 'No se pudo completar la operación.');error.fields=result.fields;error.challenge=result.challenge;error.sitekey=result.sitekey;error.status=response.status;error.path=path;throw error;}
  return result;
}
function message(form, text, success=false) {const el=form.querySelector('.message'); if(form.closest('.access-card')){const alert=!!text&&!success;el.setAttribute('role',alert?'alert':'status');el.setAttribute('aria-live',alert?'assertive':'polite');} el.textContent=text; el.classList.toggle('success',success);}
function formAction(id, action) {const form=document.getElementById(id); if(!form)return;form.addEventListener('submit',async event=>{event.preventDefault();if(form.getAttribute('aria-busy')==='true')return;if(form.closest('.access-card')&&!validateAccess(form)){return;}form.setAttribute('aria-busy','true');const button=form.querySelector('.submit');const old=Array.from(button.childNodes);button.disabled=true;button.textContent='Verificando…';message(form,'');try{await action(form, Object.fromEntries(new FormData(form)));}catch(error){if(id==='order-form'&&error.fields)setOrderErrors(error.fields);message(form,error.message);if(error.challenge)await showBot(form,error.sitekey);}finally{form.setAttribute('aria-busy','false');button.disabled=false;button.replaceChildren(...old);}});}
// Geometría de Eye / EyeOff de Lucide (ISC), SVG locales sin dependencias externas.
function passwordEye(button,show){
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','2');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('aria-hidden','true');svg.classList.add('icon');
 const paths=show?['m2 2 20 20','M10.58 10.58a2 2 0 0 0 2.84 2.84','M9.88 5.09A10.94 10.94 0 0 1 12 5c7 0 10 7 10 7a13.87 13.87 0 0 1-3.36 4.48','M6.61 6.61A13.53 13.53 0 0 0 2 12s3 7 10 7a10.94 10.94 0 0 0 5.39-1.61']:['M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0'];
 paths.forEach(d=>{const path=document.createElementNS(ns,'path');path.setAttribute('d',d);svg.append(path);});if(!show){const circle=document.createElementNS(ns,'circle');circle.setAttribute('cx','12');circle.setAttribute('cy','12');circle.setAttribute('r','3');svg.append(circle);}button.replaceChildren(svg);button.setAttribute('aria-label',show?'Ocultar contraseña':'Mostrar contraseña');button.setAttribute('aria-pressed',String(show));
}
document.querySelectorAll('.reveal').forEach(button=>{passwordEye(button,false);button.addEventListener('click',()=>{const input=document.getElementById(button.getAttribute('aria-controls'));const show=input.type==='password';input.type=show?'text':'password';passwordEye(button,show);});});
// El logotipo se utiliza sin modificar; mientras no exista, se muestra solo texto corporativo.
document.querySelectorAll('.original-logo').forEach(img=>{img.addEventListener('load',()=>{img.hidden=false;img.parentElement.querySelector('.brand-text').hidden=true;});if(img.complete && img.naturalWidth){img.hidden=false;img.parentElement.querySelector('.brand-text').hidden=true;}});
function accessError(input,text,valid=false){
 const hint=document.getElementById(input.id+'-hint');
 input.setAttribute('aria-invalid',String(!!text&&!valid));input.dataset.formatValid=String(valid);
 if(hint){hint.textContent=(valid?'✓ ':'')+text;hint.classList.toggle('valid',valid);}
}
function checkAccessField(input,submitted=false){
 const value=input.type==='password'||input.name==='repeat'?input.value:input.value.trim();
 if(!value){accessError(input,submitted?(input.name==='login'?'Escribe tu usuario o correo electrónico.':input.name==='email'?'Introduce tu correo electrónico.':input.name==='password'?'Escribe tu contraseña.':'Completa este campo.'):'');return !submitted;}
 if(input.name==='login'||input.name==='email'){
  if(input.name==='email'||value.includes('@')){const valid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);accessError(input,valid?'Formato de correo correcto.':'Revisa el formato del correo electrónico.',valid);return valid;}
 }
 if(document.body.dataset.page==='reset'){
  if(input.name==='password'&&value.length<Number(input.minLength)){accessError(input,'Usa al menos '+input.minLength+' caracteres.');return false;}
  if(input.name==='repeat'){const valid=input.value===document.getElementById('password').value;accessError(input,valid?'Las contraseñas coinciden.':'Las contraseñas no coinciden.',valid);return valid;}
 }
 accessError(input,'');return true;
}
function validateAccess(form){let first;form.querySelectorAll('input[required]').forEach(input=>{if(!checkAccessField(input,true)&&!first)first=input;});if(first)first.focus();return !first;}
document.querySelectorAll('.access-card input[required]').forEach(input=>{
 input.addEventListener('input',()=>{checkAccessField(input);if(document.body.dataset.page==='reset'&&input.name==='password'){
 const score=input.value.length<Number(input.minLength)?0:Math.min(4,Math.max(1,1+Math.floor((input.value.length-12)/6)+(new Set(input.value).size>=10?1:0)));
 document.getElementById('password-strength').value=score;document.getElementById('strength-text').textContent=['Demasiado corta','Fortaleza baja','Fortaleza media','Fortaleza alta','Frase o contraseña larga'][score];
 const repeat=document.getElementById('repeat');if(repeat.value)checkAccessField(repeat);
 }});
 input.addEventListener('blur',()=>{if(input.name==='login'||input.name==='email')input.value=input.value.trim();checkAccessField(input,true);});
});
// Aviso de Bloq Mayús en el acceso; solo informa, no modifica lo escrito.
{const password=document.querySelector('body[data-page=login] #password'),caps=document.getElementById('caps-hint');if(password&&caps){const update=event=>{if(typeof event.getModifierState==='function')caps.textContent=event.getModifierState('CapsLock')?'Bloq Mayús está activado.':'';};password.addEventListener('keydown',update);password.addEventListener('keyup',update);password.addEventListener('blur',()=>{caps.textContent='';});}}
let botScript;
async function showBot(form,sitekey){
 let container=form.querySelector('.auth-bot');if(!container){container=document.createElement('div');container.className='auth-bot';form.querySelector('.submit').before(container);}
 if(container.dataset.widget){window.turnstile?.reset(container.dataset.widget);return;}
 container.replaceChildren();const target=document.createElement('div');container.append(target);
 const alternative=document.createElement('p');alternative.textContent='Si la verificación falla, espera unos minutos o ';const link=document.createElement('a');link.href='/forgot';link.textContent='recupera tu contraseña';alternative.append(link);container.append(alternative);
 try{
 if(!window.turnstile){if(!botScript)botScript=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=resolve;script.onerror=()=>{botScript=null;reject(new Error('No se pudo cargar la verificación.'));};document.head.append(script);});await botScript;}
 container.dataset.widget=window.turnstile.render(target,{sitekey,action:document.body.dataset.page,theme:'dark',size:container.clientWidth<300?'compact':'flexible',callback:token=>{form.dataset.botToken=token;},'expired-callback':()=>{delete form.dataset.botToken;},'error-callback':()=>{delete form.dataset.botToken;message(form,'La verificación no está disponible. Espera o recupera tu contraseña.');}});
 }catch(error){message(form,error.message+' Espera e inténtalo más tarde.');}
}
async function accessApi(form,path,data){data.bot_token=form.dataset.botToken||'';try{return await api(path,data);}finally{delete form.dataset.botToken;const widget=form.querySelector('.auth-bot')?.dataset.widget;if(widget)window.turnstile?.reset(widget);}}
formAction('login-form',async(form,data)=>{data.login=data.login.trim();data.remember=form.elements.remember.checked;if(form.dataset.sitekey&&!form.dataset.botToken)throw new Error('Completa la verificación de seguridad para iniciar sesión.');const password=form.elements.password;if(password.type!=='password'){password.type='password';passwordEye(form.querySelector('.reveal'),false);}try{await accessApi(form,'/api/login',data);}catch(error){password.focus();password.select();throw error;}location.assign(/^\/orders\/[^/]{1,80}$/.test(location.pathname)?location.pathname:'/');});
{const form=document.getElementById('login-form');if(form?.dataset.sitekey)showBot(form,form.dataset.sitekey);}
formAction('forgot-form',async(form,data)=>{data.email=data.email.trim();const result=await accessApi(form,'/api/forgot',data);message(form,result.message,true);});
formAction('reset-form',async(form,data)=>{data.token=new URLSearchParams(location.search).get('token')||'';await api('/api/reset',data);form.reset();form.querySelectorAll('input,.submit').forEach(control=>control.hidden=true);form.querySelectorAll('label,.password-wrap,meter,.login-field-hint').forEach(control=>control.hidden=true);message(form,'Tu contraseña se ha actualizado correctamente',true);history.replaceState(null,'','/reset');});

