function closeIcon(action){const b=button('',action,'icon-button');b.setAttribute('aria-label','Cerrar');const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),path=document.createElementNS(ns,'path');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('class','field-icon');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','2');svg.setAttribute('aria-hidden','true');path.setAttribute('d','m6 6 12 12M18 6 6 18');svg.append(path);b.append(svg);return b;}
