 for(const row of data.rows){const tr=el('tr');const values=name==='orders'?[displayCode(row),row.client,[row.brand,row.model].filter(Boolean).join(' ')||'Sin especificar',row.status,new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil'}).format(new Date(row.created_at*1000))]:name==='clients'?[row.name,row.phone||'—',row.email||'—']:[[row.brand,row.model].filter(Boolean).join(' ')||'Sin especificar',row.client,receptionOptions?.device_types[row.type]||({portatil:'Computadora portátil',escritorio:'PC de escritorio'}[row.type]||row.type),row.serial||'—'];values.forEach((value,i)=>{const td=el('td');if(name==='orders'&&i===3)td.append(el('span',value,'status-label'));else td.textContent=value;tr.append(td);});
 if(admin()||['orders','clients'].includes(name)){const td=el('td');if(name==='orders'){td.append(button('Ver recepción',()=>showReceipt(row.id)));if(admin()){const select=el('select');select.setAttribute('aria-label','Estado de orden '+row.id);for(const [code,label]of Object.entries(statusNames)){const option=el('option',label);option.value=code;option.selected=code===row.status_code;select.append(option);}select.onchange=async()=>{select.disabled=true;try{await api('/api/order-status',{id:String(row.id),status:select.value});await renderRoute();notify('Estado actualizado.',true);}catch(e){select.value=row.status_code;select.disabled=false;notify(e.message);}};td.append(select);}}else if(name==='clients'){td.append(button('Ver cliente',()=>showClientDetail(row.id)));if(admin())td.append(button('Editar',()=>openRecord(name,row).catch(e=>notify(e.message))));}else td.append(button('Editar',()=>openRecord(name,row).catch(e=>notify(e.message))));tr.append(td);}body.append(tr);}
 table.append(body);wrap.append(table);
