 const params=new URLSearchParams({province:$('order-province_code').value,canton:$('order-canton_code').value,parish:$('order-parish_code').value});
 const key=level+'?'+params;const statusId='geo-status-'+level;operationStatus(statusId,'Cargando '+({provinces:'provincias',cantons:'cantones',parishes:'parroquias',localities:'localidades'}[level])+'…');
