let clockOffset=0,clockInterval=null,weatherInterval=null;
function formatEcuadorClock(milliseconds){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Guayaquil',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true}).formatToParts(new Date(milliseconds));const get=key=>parts.find(p=>p.type===key)?.value;return`${get('hour')}:${get('minute')}:${get('second')} ${get('dayPeriod')==='AM'?'a.m.':'p.m.'}`;}
function tickClock(){const time=Date.now()+clockOffset;$('live-clock').textContent=formatEcuadorClock(time);$('live-clock').dateTime=new Date(time).toISOString();}
async function synchronizeClock(){const start=Date.now();try{const{server_time}=await api('/api/time');clockOffset=server_time*1000-(start+Date.now())/2;tickClock();}catch(error){/* El reloj conserva el último ajuste y la zona de Ecuador. */}}
function renderWeather(data){const iconName=Object.hasOwn(weatherIcons,data.icon)?data.icon:'cloud-off';const svg=new DOMParser().parseFromString(weatherIcons[iconName],'image/svg+xml').documentElement;svg.setAttribute('class','field-icon');svg.setAttribute('aria-hidden','true');$('weather-icon').replaceChildren(document.importNode(svg,true));$('weather-temperature').textContent=data.available?data.temperature+' °C':'Clima no disponible';$('weather-condition').textContent=data.available?data.label:'';$('weather-city').textContent=data.city||'';$('header-weather').classList.toggle('weather-unavailable',!data.available);$('header-weather').title=data.available?'Pronóstico de MET Norway para la hora actual. Vigencia: '+new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',hour:'2-digit',minute:'2-digit'}).format(new Date(data.valid_at)):'Clima no disponible';}
let weatherRequest=null,weatherNextAttempt=0;
async function refreshWeather(){if(document.hidden||!$('header-weather').getClientRects().length||Date.now()<weatherNextAttempt)return;if(weatherRequest)return weatherRequest;
 weatherRequest=(async()=>{try{const data=await api('/api/weather');renderWeather(data);weatherNextAttempt=Date.now()+(data.available?600000:60000);}catch(error){renderWeather({available:false,icon:'cloud-off',city:$('weather-city').textContent});weatherNextAttempt=Date.now()+60000;}finally{weatherRequest=null;}})();return weatherRequest;
}

function initHeaderNavigation(){
 const header=document.querySelector('.premium-header'),menu=$('header-menu-toggle'),drawer=$('header-drawer'),search=$('global-search'),status=$('header-status'),tools=document.querySelector('.header-utilities'),account=$('account-toggle'),panel=$('account-panel');
 let menuOpen=false,accountOpen=false,returnFocus=menu;
 function closeAssistance(){const assistance=$('assistance-menu');if(assistance)assistance.open=false;}
 function closeAccount(focus=false){accountOpen=false;panel.hidden=true;account.setAttribute('aria-expanded','false');if(focus)account.focus();}
 function setMenu(open,focus=false){menuOpen=open;drawer.hidden=innerWidth<1000&&!open;menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Cerrar navegación principal':'Abrir navegación principal');if(open){closeAccount();refreshWeather();}if(focus)returnFocus.focus();}
 function adapt(){
  if(innerWidth<=860)$('header-search-slot').append(search);else tools.insertBefore(search,tools.querySelector('#header-status')||tools.querySelector('.user-area'));
  if(innerWidth<1000)$('header-status-slot').append(status);else tools.insertBefore(status,tools.querySelector('.user-area'));
  setMenu(false);closeAccount();
 }
 menu.addEventListener('click',()=>{returnFocus=menu;setMenu(!menuOpen);});
 $('header-search-toggle').addEventListener('click',()=>{returnFocus=$('header-search-toggle');setMenu(true);$('search').focus();});
 account.addEventListener('click',()=>{const open=!accountOpen;setMenu(false);accountOpen=open;panel.hidden=!open;account.setAttribute('aria-expanded',String(open));});
 drawer.querySelectorAll('[data-nav]').forEach(link=>link.addEventListener('click',()=>{closeAssistance();setMenu(false);}));
 search.addEventListener('submit',()=>setMenu(false));
 document.addEventListener('click',event=>{if(!event.target.closest('.assistance-menu'))closeAssistance();if(!header.contains(event.target)){setMenu(false);closeAccount();}else if(!event.target.closest('.user-area'))closeAccount();});
 document.addEventListener('keydown',event=>{if(event.key==='Escape'){if($('assistance-menu').open){closeAssistance();$('assistance-menu').querySelector('summary').focus();event.preventDefault();}else if(accountOpen){closeAccount(true);event.preventDefault();}else if(menuOpen){setMenu(false,true);event.preventDefault();}}});
 for(const query of ['(max-width: 999px)','(max-width: 1150px)','(max-width: 860px)'])matchMedia(query).addEventListener('change',adapt);
 adapt();
}

function initHeader(serverTime){if(serverTime)clockOffset=serverTime*1000-Date.now();tickClock();clockInterval=setInterval(tickClock,1000);synchronizeClock();refreshWeather();weatherInterval=setInterval(()=>{synchronizeClock();refreshWeather();},600000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){tickClock();refreshWeather();}});const media=matchMedia('(min-width: 1151px)');media.addEventListener('change',()=>refreshWeather());}

