function formatOrderDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'No registrada':new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(date);}
