async function showClientForm(id=null,fromOrder=false){clientReturn=fromOrder;clientEditing=id?String(id):'';const form=$('client-form');if(fromOrder&&$('order-dialog').open)$('order-dialog').close();form.querySelectorAll('[name=document_type] option').forEach(option=>option.disabled=false);form.reset();if(!id)form.elements.document_type.value='cedula';form.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));form.querySelectorAll('.field-error').forEach(x=>x.textContent='');for(const name of geoFields)$('order-'+name+'_code').value='';clearGeoBelow(0);identificationTypeChanged();message(form,'');showClientStep(0);$('client-dialog').showModal();await loadReceptionOptions();if(!geoState.provinces.length)await fetchGeo('provinces');$('order-province').disabled=false;if(id){try{const{client}=await api('/api/clients/'+id);for(const input of form.elements){if(input.name&&client[input.name]!=null)input.value=client[input.name];}form.elements.client.value=client.name;identificationTypeChanged();for(let i=0;i<3;i++){const name=geoFields[i];$('order-'+name+'_code').value=client[name+'_code'];$('order-'+name).value=client[name]+' · '+client[name+'_code'];if(i<2)await fetchGeo(geoLevels[i+1]);}await fetchGeo('localities');$('order-city').value=client.city;$('order-locality_code').value=client.locality_code||'';}catch(e){message(form,e.message);}}form.dataset.initial=formSnapshot(form);$('client-heading-0').focus();}
function showClientStep(step){clientStep=Math.max(0,Math.min(2,step));const form=$('client-form');form.querySelectorAll('[data-client-panel]').forEach(p=>p.hidden=+p.dataset.clientPanel!==clientStep);form.querySelectorAll('[data-client-step]').forEach(b=>{b.disabled=+b.dataset.clientStep>clientStep;b.setAttribute('aria-current',+b.dataset.clientStep===clientStep?'step':'false');});$('client-back').disabled=clientStep===0;$('client-next').hidden=clientStep===2;form.querySelector('.submit').hidden=clientStep!==2;if(clientStep===2){const data=Object.fromEntries(new FormData(form));$('client-summary').replaceChildren();for(const[label,value]of [['Cliente',data.client],['Identificación',data.identification],['Contacto',[data.phone,data.email].filter(Boolean).join(' · ')],['Ubicación',[data.province,data.canton,data.parish,data.city].filter(Boolean).join(' / ')],['Dirección',[data.main_street,data.building_number,data.secondary_street,data.location_reference].filter(Boolean).join(', ')]])$('client-summary').append(el('h4',label),el('p',value));}$('client-heading-'+clientStep).focus();form.querySelector('.reception-scroll').scrollTop=0;}
function clientErrors(all=false){const form=$('client-form'),data=Object.fromEntries(new FormData(form)),errors={};for(const input of form.querySelectorAll('input,select,textarea')){if(!all&&+input.closest('[data-client-panel]')?.dataset.clientPanel!==clientStep)continue;if(input.required&&!['radio','checkbox'].includes(input.type)&&!input.value.trim())errors[input.name]='Completa este campo.';if(input.type==='email'&&input.value&&!input.validity.valid)errors.email='Ingresa un correo válido.';if(input.name==='phone'&&input.value&&!validEcuadorPhone(input.value))errors.phone='Ingresa un móvil 09…, fijo con código de área o +593….';}if(all||clientStep===0){const value=data.identification||'',type=data.document_type;const error=type==='pasaporte'?(/^[A-Za-z0-9-]{3,30}$/.test(value)?'':'Ingresa un pasaporte válido.'):value.length!==(type==='ruc'?13:10)?'Revisa la longitud de la identificación.':documentError(value);if(error)errors.identification=error;if(data.client_type==='empresa'&&type!=='ruc')errors.document_type='Selecciona RUC para una empresa.';}if(all||clientStep===1)for(const name of geoFields)if(!data[name+'_code'])errors[name]='Selecciona una opción del catálogo.';return errors;}
function showClientErrors(errors){const form=$('client-form');form.querySelectorAll('.field-error').forEach(n=>n.textContent='');form.querySelectorAll('[aria-invalid]').forEach(n=>n.removeAttribute('aria-invalid'));let first;for(const[key,value]of Object.entries(errors)){const input=form.elements.namedItem(key==='name'?'client':key.endsWith('_code')?key.slice(0,-5):key);if(input){first=first||input;input.setAttribute('aria-invalid','true');const error=$('error-'+input.name);if(error)error.textContent=value;}}if(first){showClientStep(+first.closest('[data-client-panel]')?.dataset.clientPanel||0);first.focus();}}
