async function renderMaintenance(){const data=await api('/api/maintenance'),root=$('module-content');root.replaceChildren();const filters=el('form',undefined,'module-tools');const state=field(filters,'Mostrar','state','',{select:true});for(const[value,label]of [['','Todos'],['upcoming','Próximos'],['month','Este mes'],['overdue','Vencidos'],['sent','Recordatorios enviados'],['appointment','Citas confirmadas'],['completed','Realizados']]){const o=el('option',label);o.value=value;state.append(o);}const type=field(filters,'Tipo de equipo','type','',{select:true});type.append(el('option','Todos'));type.firstChild.value='';await loadReceptionOptions();for(const[value,label]of Object.entries(receptionOptions.device_types)){const o=el('option',label);o.value=value;type.append(o);}const from=field(filters,'Desde','from','',{type:'date'}),to=field(filters,'Hasta','to','',{type:'date'});root.append(filters);const list=el('div');root.append(list);function draw(){const orderFilter=routeState().params.get('order');const rows=data.rows.filter(r=>(!orderFilter||String(r.order_id)===orderFilter)&&(!type.value||r.type===type.value)&&(!from.value||r.due_date>=from.value)&&(!to.value||r.due_date<=to.value)&&(!state.value||state.value==='upcoming'&&r.due_date>=data.today&&r.state==='scheduled'||state.value==='month'&&r.due_date.slice(0,7)===data.today.slice(0,7)||state.value==='overdue'&&r.due_date<data.today&&r.state==='scheduled'||state.value==='sent'&&r.reminder==='accepted'||r.state===state.value));renderMaintenanceRows(list,rows,data.today);}filters.onchange=draw;filters.onsubmit=e=>e.preventDefault();draw();}
