function initOperationSearch(){const form=$('global-search'),input=$('search'),list=el('div',undefined,'global-search-results');list.id='global-search-results';list.hidden=true;list.setAttribute('role','listbox');list.setAttribute('aria-label','Resultados de búsqueda');form.append(list);input.setAttribute('aria-controls',list.id);input.setAttribute('aria-expanded','false');let timer,version=0;function hide(){list.hidden=true;input.setAttribute('aria-expanded','false');}input.addEventListener('input',()=>{clearTimeout(timer);const token=++version;const term=input.value.trim();if(term.length<2){hide();return;}timer=setTimeout(async()=>{try{const data=await api('/api/search?q='+encodeURIComponent(term));if(token!==version)return;list.replaceChildren();for(const row of data.rows){const result=button('',()=>{hide();go('orders',new URLSearchParams({id:row.id}));},'global-search-result');result.setAttribute('role','option');result.append(el('strong',row.code),el('span',row.client+' · '+[row.brand,row.model].filter(Boolean).join(' ')),el('small',row.status+' · '+(row.serial||'Sin serie')));list.append(result);}if(!data.rows.length)list.append(el('p','No se encontraron órdenes.'));list.hidden=false;input.setAttribute('aria-expanded','true');}catch(e){hide();notify(e.message);}},220);});input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'&&!list.hidden){e.preventDefault();list.querySelector('button')?.focus();}if(e.key==='Escape')hide();});list.addEventListener('keydown',e=>{const items=[...list.querySelectorAll('button')],i=items.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();items[(i+1)%items.length]?.focus();}if(e.key==='ArrowUp'){e.preventDefault();if(i<=0)input.focus();else items[i-1].focus();}if(e.key==='Escape'){hide();input.focus();}});document.addEventListener('click',e=>{if(!form.contains(e.target))hide();});form.addEventListener('submit',hide);$('quick-client').prepend(operationIcon('client'));$('quick-order').prepend(operationIcon('order'));$('quick-appointment').prepend(operationIcon('calendar'));setInterval(()=>{if(currentModule==='home'&&!document.hidden&&!$('order-dialog').open&&!$('client-dialog').open)refresh().catch(e=>notify(e.message));},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&currentModule==='home')refresh().catch(e=>notify(e.message));});}

