function renderAppointmentSettings(root,settings){if(!settings)return;const details=el('details',undefined,'appointment-config');details.append(el('summary','Configurar horarios, servicios y feriados'));const form=el('form');for(const h of settings.hours){const row=el('label',(['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'][h.weekday]));const active=el('input');active.type='checkbox';active.checked=!!h.enabled;active.dataset.weekday=h.weekday;const start=el('input');start.type='time';start.value=h.start_time;start.dataset.start=h.weekday;const end=el('input');end.type='time';end.value=h.end_time;end.dataset.end=h.weekday;row.append(active,start,end);form.append(row)}for(const h of settings.staff_hours||[]){const row=el('label',h.technician+' · '+(['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'][h.weekday]));const active=el('input');active.type='checkbox';active.checked=!!h.enabled;active.dataset.staffEnabled=h.technician_id+'-'+h.weekday;const start=el('input');start.type='time';start.value=h.start_time;start.dataset.staffStart=h.technician_id+'-'+h.weekday;const end=el('input');end.type='time';end.value=h.end_time;end.dataset.staffEnd=h.technician_id+'-'+h.weekday;row.append(active,start,end);form.append(row)}for(const svc of settings.services){const row=el('label',svc.label+' · minutos');const duration=el('input');duration.type='number';duration.min='15';duration.max='240';duration.step='15';duration.value=svc.duration_minutes;duration.dataset.service=svc.code;const enabled=el('input');enabled.type='checkbox';enabled.checked=!!svc.active;enabled.dataset.active=svc.code;row.append(duration,enabled);form.append(row)}const holiday=el('div',undefined,'appointment-holiday');const day=el('input');day.type='date';day.setAttribute('aria-label','Día no laborable');const reason=el('input');reason.placeholder='Motivo';reason.maxLength=100;holiday.append(day,reason,button('Agregar feriado',async()=>{try{await api('/api/appointments/config',{holiday:{day:day.value,label:reason.value}});notify('Día no laborable guardado.',true);renderAppointments()}catch(e){notify(e.message)}}));for(const h of settings.holidays){holiday.append(el('span',h.day+' · '+h.label),button('Quitar',async()=>{try{await api('/api/appointments/config',{remove_holiday:h.day});renderAppointments()}catch(e){notify(e.message)}}))}form.append(holiday);form.append(button('Guardar configuración',async()=>{const hours=settings.hours.map(h=>({weekday:h.weekday,start_time:form.querySelector('[data-start="'+h.weekday+'"]').value,end_time:form.querySelector('[data-end="'+h.weekday+'"]').value,enabled:form.querySelector('[data-weekday="'+h.weekday+'"]').checked}));const services=settings.services.map(s=>({code:s.code,duration_minutes:Number(form.querySelector('[data-service="'+s.code+'"]').value),active:form.querySelector('[data-active="'+s.code+'"]').checked}));const staff_hours=(settings.staff_hours||[]).map(h=>{const key=h.technician_id+'-'+h.weekday;return{technician_id:h.technician_id,weekday:h.weekday,start_time:form.querySelector('[data-staff-start="'+key+'"]').value,end_time:form.querySelector('[data-staff-end="'+key+'"]').value,enabled:form.querySelector('[data-staff-enabled="'+key+'"]').checked}});try{await api('/api/appointments/config',{hours,services,staff_hours});notify('Configuración de agenda guardada.',true);renderAppointments()}catch(e){notify(e.message)}},'primary'));details.append(form);root.append(details)}
