async function renderLive(){const root=$('module-content');root.replaceChildren();const layout=el('div',undefined,'live-layout'),list=el('div',undefined,'live-list'),chat=el('section',undefined,'live-chat');layout.append(list,chat);root.append(layout);await loadLiveList();window.__loadLiveList=loadLiveList;async function loadLiveList(){try{const d=await api('/api/adi/live');list.replaceChildren();if(!d.rows.length)list.append(el('p','No hay conversaciones activas.','empty-module'));for(const row of d.rows){const b=button('',()=>openConversation(row.id),'live-conversation');b.append(el('strong','Conversación '+row.id+' · '+(row.mode==='human'?'Atención humana':row.mode==='adi'?'Adi':'Cerrada')),el('small',row.last_message||'Sin mensajes'));list.append(b)}}catch(e){list.replaceChildren(el('p',e.message))}}async function openConversation(id){activeConversation=id;adminMessageCursor=0;const d=await api('/api/adi/live/'+id);chat.replaceChildren(el('h2','Conversación '+id+' · '+d.conversation.mode));for(const m of d.messages){const line=el('p',m.author+': '+m.content,'adi-message '+m.author);chat.append(line);adminMessageCursor=Math.max(adminMessageCursor,m.id)}const actions=el('div',undefined,'live-actions');actions.append(button('Tomar conversación',()=>liveAction(id,'takeover'), 'secondary'),button('Reactivar Adi',()=>liveAction(id,'resume'),'secondary'),button('Cerrar',()=>liveAction(id,'close'),'secondary'));chat.append(actions);const form=el('form');const input=el('input');input.placeholder='Responder al cliente';input.required=true;const send=el('button','Enviar','primary');form.append(input,send);form.onsubmit=async e=>{e.preventDefault();if(send.disabled)return;send.disabled=true;try{await api('/api/adi/live/'+id,{action:'reply',message:input.value});input.value='';openConversation(id);loadLiveList()}catch(err){notify(err.message);send.disabled=false}};chat.append(form)}async function liveAction(id,action){try{await api('/api/adi/live/'+id,{action});openConversation(id);loadLiveList()}catch(e){notify(e.message)}}setInterval(()=>{if(currentModule==='live'){loadLiveList();pollLiveConversation(chat)}},2500)}
