async function pollLiveConversation(chat){if(!activeConversation||!chat)return;try{const d=await api('/api/adi/live/'+activeConversation+'?after='+adminMessageCursor);for(const m of d.messages){const line=el('p',m.author+': '+m.content,'adi-message '+m.author);chat.insertBefore(line,chat.querySelector('form'));adminMessageCursor=Math.max(adminMessageCursor,m.id)}const title=chat.querySelector('h2');if(title)title.textContent='Conversación '+activeConversation+' · '+d.conversation.mode}catch{}}
async function renderAdminAdi(){const root=$('module-content');root.replaceChildren();const form=el('form',undefined,'adi-admin-form');const input=el('input');input.setAttribute('aria-label','Consulta administrativa para Adi');input.placeholder='¿Cuántas órdenes esperan respuesta?';input.required=true;input.maxLength=2000;const send=el('button','Consultar','primary');form.append(input,send);const answer=el('section',undefined,'workspace-section');answer.append(el('p','Las consultas operativas se responden con datos registrados. Las modificaciones deben confirmarse y ejecutarse desde el módulo autorizado.'));form.onsubmit=async e=>{e.preventDefault();if(send.disabled)return;send.disabled=true;try{const r=await api('/api/adi/admin',{message:input.value});answer.replaceChildren(el('p',r.answer));input.value=''}catch(err){answer.replaceChildren(el('p',err.message))}finally{send.disabled=false}};root.append(form,answer)}

let lastModalTrigger=null;document.addEventListener('focusin',event=>{if(!event.target.closest('dialog'))lastModalTrigger=event.target;});
function requestModalClose(dialog){const form=dialog.querySelector('form');if(form){if([...form.querySelectorAll('button')].some(button=>button.type==='submit'&&button.disabled)||form.getAttribute('aria-busy')==='true')return;if(dialog.dataset.baseline&&formSnapshot(form)!==dialog.dataset.baseline&&!confirm('Hay cambios sin guardar. ¿Descartarlos y cerrar?'))return;}dialog.close();}
function enhanceModal(dialog){if(dialog.dataset.enhanced||dialog.id==='order-dialog'||dialog.id==='client-dialog'||dialog.id==='receipt-dialog')return;dialog.dataset.enhanced='true';const heading=dialog.querySelector('form>header,.dialog-heading');if(heading){const old=heading.querySelector('button');if(old)old.replaceWith(closeIcon(()=>requestModalClose(dialog)));else heading.append(closeIcon(()=>requestModalClose(dialog)));}
 dialog.addEventListener('cancel',e=>{e.preventDefault();requestModalClose(dialog);});let opener=lastModalTrigger||document.activeElement;
 function capture(){if(dialog.open){opener=lastModalTrigger||opener;const form=dialog.querySelector('form');if(form)dialog.dataset.baseline=formSnapshot(form);}}
 new MutationObserver(capture).observe(dialog,{attributes:true,attributeFilter:['open']});capture();dialog.addEventListener('close',()=>{if(opener?.isConnected&&!opener.closest('dialog'))opener.focus();});}
if(document.body.dataset.page==='dashboard'){document.querySelectorAll('dialog').forEach(enhanceModal);new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node.nodeType===1){if(node.matches('dialog'))enhanceModal(node);node.querySelectorAll('dialog').forEach(enhanceModal);}}).observe(document.body,{childList:true});}

const accessScopeLabels={operating_system:'Acceso al sistema operativo',signed_in_tests:'Pruebas de funcionamiento con sesión iniciada',specific_files:'Acceso a archivos específicos',backup:'Respaldo de información'};
function accessFields(prefix){
 const box=el('fieldset',undefined,'technical-access-fields');box.append(el('legend','AUTORIZACIÓN DE ACCESO TÉCNICO'),el('p','El acceso técnico puede comprender el ingreso al sistema operativo y la ejecución de pruebas de funcionamiento. La revisión de archivos personales, cuentas o información privada requiere autorización específica y justificación técnica.','small'));
 const options=el('div',undefined,'access-options');for(const[value,text]of [['authorized','Sí autorizo acceso técnico'],['denied','No autorizo acceso técnico']]){const label=el('label'),input=el('input');input.type='radio';input.name='technical_access';input.value=value;input.required=true;input.setAttribute('aria-describedby',prefix==='order'?'error-technical_access':prefix+'-technical_access');label.append(input,el('span',text));options.append(label);}box.append(options);
 function error(name){const small=el('small','','field-error');small.id=prefix==='order'?'error-'+name:prefix+'-'+name;small.dataset.accessError=name;small.setAttribute('aria-live','polite');box.append(small);}
 error('technical_access');
 const scopes=el('div',undefined,'access-options');for(const[key,text]of Object.entries(accessScopeLabels)){const label=el('label'),input=el('input');input.type='checkbox';input.name='access_'+key;input.disabled=true;label.append(input,el('span',text));scopes.append(label);}box.append(scopes);
 const detail=field(box,'Archivos/datos acordados y justificación técnica (sin contraseñas)','access_detail','',{textarea:true,maxLength:1000});error('access_detail');
 const confirmed=el('label',undefined,'access-confirm'),check=el('input');check.type='checkbox';check.name='access_confirmed';confirmed.append(check,el('span','Confirmo que el cliente expresó esta decisión y el alcance seleccionado.'));box.append(confirmed);error('access_confirmed');
 const destructive=field(box,'Autorización adicional: reinstalar, formatear o eliminar información','destructive_action','',{select:true});for(const[value,text]of [['not_requested','No solicitada: sin autorización adicional'],['authorized','Sí, mediante autorización adicional expresa'],['denied','No autorizo reinstalar ni eliminar información']]){const option=el('option',text);option.value=value;destructive.append(option);}
 const destructiveDetail=field(box,'Operación y datos afectados (autorización adicional)','destructive_detail','',{textarea:true,maxLength:1000});const destructiveLabel=el('label',undefined,'access-confirm'),destructiveCheck=el('input');destructiveCheck.type='checkbox';destructiveCheck.name='destructive_confirmed';destructiveLabel.append(destructiveCheck,el('span','El cliente autorizó por separado esta operación y conoce el riesgo de pérdida de información.'));box.append(destructiveLabel);error('destructive_action');error('destructive_detail');
 function update(){const authorized=box.querySelector('[name=technical_access]:checked')?.value==='authorized';for(const input of scopes.querySelectorAll('input')){input.disabled=!authorized;if(!authorized)input.checked=false;}detail.parentElement.hidden=!authorized;const extra=destructive.value==='authorized';destructiveDetail.parentElement.hidden=!extra;destructiveLabel.hidden=!extra;if(!extra){destructiveCheck.checked=false;destructiveDetail.value='';}}
 box.addEventListener('change',update);update();return box;
}
function accessPayload(form){const values=Object.fromEntries(new FormData(form)),data={};for(const name of ['technical_access','access_detail','destructive_action','destructive_detail'])if(values[name]!==undefined)data[name]=values[name];for(const name of ['access_confirmed','destructive_confirmed',...Object.keys(accessScopeLabels).map(k=>'access_'+k)])data[name]=!!form.querySelector('[name="'+name+'"]')?.checked;return data;}
function accessErrors(data){const errors={};if(!['authorized','denied'].includes(data.technical_access))errors.technical_access='Selecciona expresamente si el cliente autoriza o no el acceso.';if(!data.access_confirmed)errors.access_confirmed='Confirma la decisión expresada por el cliente.';if(data.technical_access==='authorized'&&!Object.keys(accessScopeLabels).some(k=>data['access_'+k]))errors.technical_access='Selecciona al menos una operación autorizada.';if((data.access_specific_files||data.access_backup)&&!data.access_detail?.trim())errors.access_detail='Indica los datos acordados y la justificación técnica.';if(data.destructive_action==='authorized'&&(!data.destructive_confirmed||!data.destructive_detail?.trim()))errors.destructive_action='Registra alcance y confirmación independiente para esta operación.';return errors;}
function appendAccessEvidence(root,order){const section=el('section',undefined,'terms-evidence');section.append(el('h3','Autorización de acceso técnico'));const a=order.access_authorization;section.append(el('p',a?'Acceso técnico: '+(a.decision==='authorized'?'AUTORIZADO':'NO AUTORIZADO'):'No consta autorización'));if(a){section.append(el('p','Decisión: '+formatOrderDate(a.recorded_at)+' · Responsable: '+a.operator));section.append(el('p','Alcance: '+(Object.entries(accessScopeLabels).filter(([k])=>a.permissions[k]).map(([,v])=>v).join('; ')||'Sin acceso permitido')));if(a.justification)section.append(el('p',a.justification));}const d=order.destructive_authorization;section.append(el('p','Reinstalación / eliminación: '+(d?(d.decision==='authorized'?'Autorización adicional registrada':'NO AUTORIZADO'):'Sin autorización adicional')));if(d)section.append(el('p',formatOrderDate(d.recorded_at)+' · '+d.operator+' · '+d.justification));if(order.access_history?.length){const details=el('details');details.append(el('summary','Historial de decisiones ('+order.access_history.length+')'));for(const row of order.access_history)details.append(el('p',formatOrderDate(row.recorded_at)+' · '+(row.action==='technical'?'Acceso técnico':'Reinstalación / eliminación')+' · '+(row.decision==='authorized'?'Autorizado':'No autorizado')+' · '+row.operator));section.append(details);}root.append(section);}
async function openAccessAuthorization(order){
 const dialog=el('dialog',undefined,'workspace-editor');dialog.setAttribute('aria-label','Registrar decisión expresa del cliente');const form=el('form');form.noValidate=true;const header=el('header');header.append(el('h2','Autorización · '+order.code),closeIcon(()=>requestModalClose(dialog)));const body=el('div',undefined,'workspace-edit-fields');const access=accessFields('authorization');access.classList.add('full');body.append(access);let terms=null;
 if(!order.terms){const section=el('section',undefined,'full');try{const data=await api('/api/conditions/current');terms=data.terms;if(terms){section.append(el('h3','Condiciones completas · '+terms.version),el('div',terms.full_text,'terms-full-text'));const label=el('label',undefined,'access-confirm'),check=el('input');check.type='checkbox';check.name='complete_terms';label.append(check,el('span','El cliente ha leído esta versión y acepta las condiciones ahora. No se atribuye aceptación a la fecha original.'));section.append(label);}else section.append(el('p','No hay condiciones vigentes publicadas. Puede registrar únicamente la decisión de acceso.'));}catch(e){section.append(el('p',e.message));}body.append(section);}
 const status=el('p','','message');status.setAttribute('role','status');const footer=el('footer'),save=el('button','Guardar decisión','primary');save.type='submit';footer.append(button('Cancelar',()=>requestModalClose(dialog)),save);form.append(header,body,status,footer);dialog.append(form);document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();header.querySelector('h2').tabIndex=-1;header.querySelector('h2').focus();newRequestKey(form);
 form.onsubmit=async e=>{e.preventDefault();if(save.disabled)return;const payload=accessPayload(form),errors=accessErrors(payload);access.querySelectorAll('[data-access-error]').forEach(x=>x.textContent=errors[x.dataset.accessError]||'');if(Object.keys(errors).length){status.textContent='Revisa los campos señalados.';return;}save.disabled=true;payload.access_revision=String(order.access_revision);payload.request_key=form.dataset.requestKey;payload.complete_terms=!!form.elements.complete_terms?.checked;if(payload.complete_terms){payload.terms_document_id=terms.id;payload.terms_accept=true;}try{await api('/api/orders/'+order.id+'/authorizations',payload);dialog.close();await showOrderDetail(order.id);notify('Decisión registrada con fecha, hora y usuario responsable.',true);}catch(err){status.textContent=err.message;}finally{save.disabled=false;}};
}

function renderOrdersList(data,params){
 const root=$('module-content');root.replaceChildren();const add=$('module-add');add.hidden=false;add.textContent='+ Nueva orden';add.onclick=()=>showOrder();
 const search=el('form',undefined,'orders-search');search.setAttribute('role','search');search.setAttribute('aria-label','Buscar órdenes');const input=el('input');input.type='search';input.name='q';input.maxLength=150;input.value=params.get('q')||'';input.placeholder='Número de orden, cliente, equipo, identificación o teléfono';input.setAttribute('aria-label','Buscar por orden, cliente, equipo, identificación o teléfono');const submit=el('button','Buscar','primary');submit.type='submit';search.append(input,submit);search.onsubmit=async e=>{e.preventDefault();if(submit.disabled)return;submit.disabled=true;const value=input.value.trim();try{if(/^(?:PCD-\d{8}-\d{4,}|OP-\d+)$/i.test(value)){try{const match=await api('/api/order-by-code/'+encodeURIComponent(value.toUpperCase()));go('orders',new URLSearchParams({id:String(match.id)}));return;}catch(error){if(error.status!==404)throw error;}}const next=new URLSearchParams(params);next.delete('page');if(value)next.set('q',value);else next.delete('q');go('orders',next);}catch(error){notify(error.message);}finally{submit.disabled=false;}};root.append(search);appendOrderFilters(root,params);
 const results=el('section',undefined,'data-panel orders-results');results.setAttribute('aria-label','Resultados de órdenes');const bar=el('div',undefined,'orders-results-heading');const count=el('p',data.total+(data.total===1?' registro':' registros'),'result-count');count.setAttribute('role','status');bar.append(count,el('small',data.total?'Mostrando '+((data.page-1)*50+1)+'–'+Math.min(data.page*50,data.total)+' de '+data.total:'Sin resultados'));results.append(bar);const wrap=el('div');if(data.rows.length)renderOrderCards(wrap,data.rows);else{wrap.className='orders-empty';wrap.append(operationIcon('order'),el('h3',params.size?'No hay órdenes para esta búsqueda.':'Todavía no hay órdenes registradas.'),el('p',params.size?'Ajusta la búsqueda o los filtros para encontrar otras órdenes.':'Registra una orden para iniciar el seguimiento del equipo.'));}results.append(wrap);
 const pager=el('nav',undefined,'pager orders-pagination');pager.setAttribute('aria-label','Paginación de órdenes');const previous=button('Anterior',()=>page(-1)),next=button('Siguiente',()=>page(1));previous.disabled=data.page<=1;next.disabled=data.page>=data.pages;const indicator=el('span',`Página ${data.page} de ${data.pages}`);indicator.setAttribute('aria-current','page');pager.append(previous,indicator,next);results.append(pager);root.append(results);
 function page(offset){const next=new URLSearchParams(params);next.set('page',String(data.page+offset));go('orders',next);}
}
function orderActionsMenu(row){
 const trigger=button('Más acciones',toggle,'orders-more-trigger');trigger.setAttribute('aria-haspopup','menu');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-label','Más acciones de '+displayCode(row));const menu=el('div',undefined,'orders-action-menu');menu.id='orders-actions-'+row.id;menu.dataset.orderActionPopover='true';menu.setAttribute('role','menu');menu.setAttribute('aria-label','Acciones de '+displayCode(row));trigger.setAttribute('aria-controls',menu.id);const native=typeof menu.showPopover==='function';if(native)menu.setAttribute('popover','auto');else menu.hidden=true;document.body.append(menu);
 function isOpen(){return native?menu.matches(':popover-open'):!menu.hidden;}
 function close(restore=false){if(native&&isOpen())menu.hidePopover();else if(!native)menu.hidden=true;trigger.setAttribute('aria-expanded','false');if(restore)trigger.focus();}
 function toggle(){if(isOpen()){close();return;}document.querySelectorAll('[data-order-action-popover]').forEach(other=>{if(other===menu)return;if(typeof other.hidePopover==='function'){if(other.matches(':popover-open'))other.hidePopover();}else other.hidden=true;});if(native)menu.showPopover();else menu.hidden=false;trigger.setAttribute('aria-expanded','true');const r=trigger.getBoundingClientRect(),m=menu.getBoundingClientRect(),margin=12;menu.style.left=Math.max(margin,Math.min(r.right-m.width,innerWidth-m.width-margin))+'px';menu.style.top=(r.bottom+m.height+margin<=innerHeight?r.bottom+6:Math.max(margin,r.top-m.height-6))+'px';menu.querySelector('button')?.focus();}
 if(native)menu.addEventListener('toggle',()=>trigger.setAttribute('aria-expanded',String(isOpen())));
 function item(label,action,icon){const b=button('',()=>{close(true);Promise.resolve().then(action).catch(error=>notify(error.message));},'orders-menu-item');b.setAttribute('role','menuitem');b.append(orderActionIcon(icon),document.createTextNode(label));menu.append(b);}
 if(admin()){item('Editar',()=>openOrderEditor(row.id),'edit');item('Cambiar estado',()=>openOrderStatusDialog(row),'service');}
 item('Ver historial',()=>go('orders',new URLSearchParams({id:String(row.id),section:'history'})),'service');item('Reimprimir comprobante',()=>showDocumentPreview(row.id,'receipt'),'document');item('Compartir',()=>shareReceipt(row.id),'share');item('Etiqueta de servicio',()=>printEquipmentLabel(row),'tag');item('Duplicar orden',()=>duplicateOrder(row.id),'document');
 menu.addEventListener('keydown',e=>{const items=[...menu.querySelectorAll('button')],index=items.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();close(true);}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[next].focus();}});trigger.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();if(!isOpen())toggle();}});return trigger;
}
function dismissOrderMenus(event){document.querySelectorAll('[data-order-action-popover]').forEach(menu=>{const trigger=document.querySelector('[aria-controls="'+menu.id+'"]');if(event?.type==='click'&&(menu.contains(event.target)||trigger?.contains(event.target)))return;if(typeof menu.hidePopover==='function'){if(menu.matches(':popover-open'))menu.hidePopover();}else menu.hidden=true;trigger?.setAttribute('aria-expanded','false');});}
document.addEventListener('click',dismissOrderMenus);window.addEventListener('resize',dismissOrderMenus);document.addEventListener('scroll',event=>{if(!event.target.closest?.('[data-order-action-popover]'))dismissOrderMenus();},true);
function openOrderStatusDialog(row){
 const dialog=smallDialog('Cambiar estado · '+displayCode(row)),form=el('form');form.className='orders-status-form';const select=field(form,'Estado de la orden','status',row.status_code,{select:true});for(const[code,label]of Object.entries(statusNames))select.append(new Option(label,code));select.value=row.status_code;const message=el('p','','message');message.setAttribute('role','status');const save=el('button','Guardar estado','primary');save.type='submit';form.append(message,save);dialog.append(form);select.focus();form.onsubmit=async event=>{event.preventDefault();if(save.disabled)return;save.disabled=true;try{await api('/api/order-status',{id:String(row.id),status:select.value});dialog.close();await renderRoute();notify('Estado actualizado.',true);}catch(error){message.textContent=error.message;}finally{save.disabled=false;}};
}
